-- 0116：企劃工作臺定稿（2026-11-03 六六：抓定稿進來，觀貓事件與江湖事件稱號給太多要拿掉）
--
-- 一、觀貓第一章「初識觀貓」（工作臺 lingshou_c1 第 306 版，final，11-03）：線上原本沒有這一章，新增。
--     獎勵只有靈石 10＋他的身分「喵喵喵」（玩家稱號不發）。身分由 0065 的 trigger 自動建 character_titles 一列，這裡補聲口與說明。
--     前端道緣事件目前全部關著（STORY_OPEN_CIDS 清空），上架不會馬上被玩到。
-- 二、乾為天（工作臺 gua_01，final，11-01）：結局只剩「亢龍有悔」發稱號「悔亡」，其餘六個結局不發。
--     內容與 0110（10-24 版）相同，只是狀態改 final。
-- 三、拿掉舊版發出去的江湖稱號：0100 那版五個結局各發一個（拆旗人、目送者、同登者、觀台客、潛龍），
--     玩家走過就已經拿到。把乾為天現在不發的稱號整列刪掉（user_player_titles 跟著 cascade；
--     profiles.player_title 自動變 null，title_tag 另外清掉，廣場才不會還顯示舊字）。
--     「亢龍有悔」的稱號 id 沒變（jh01_e9ay6i），舊字是「目送者」：直接改成「悔亡」，拿過的人改拿悔亡。

insert into character_events (id, character_id, chapter, seq, title, summary, require_favor, require_cultivation, require_event,
  scenes, choices, rewards, reward_lingshi, reward_avatar, reward_title, reward_memory, published)
values ('lingshou_c1', 'lingshou', 1, 1, '初識觀貓', '這貓成精了！', 0, 0, null,
  $sc$[{"bg": "dadian", "place": "正殿・晨間", "text": "晨光透進幾知觀正殿。大師兄站在卦案前，動作機械地將籤條歸位。\n一隻棕色虎斑貓蹲在卦案中央，尾巴懶散地繞過籤筒底端，佔據了整張桌面的核心位置。"}, {"portrait": "daoshi_m", "who": "daoshi_m", "text": "「......你，請留步。」\n他將最後一支籤條壓入筒中。\n「卦案被佔用了，不起來......偏殿稍後吧。」"}, {"me": true, "text": "（我注意到那隻貓頸上的銅牌刻著『知』字。）\n那貓注意到你的視線，懶懶地抖抖耳朵。"}, {"portrait": null, "who": "daoshi_m", "text": "他將籤筒移至桌角，避開貓的爪子。\n「請至偏殿候茶。」\n語氣平直，沒有多餘的解釋。"}, {"bg": "qianting", "place": "前廳・偏殿", "text": "偏殿內茶香淺淡。師妹坐在案後，指尖輕抵唇邊，目光掃過玩家的衣料與腰間銅錢。\n她嘴角噙著一絲得體的笑意。"}, {"portrait": "daoshi_f", "who": "daoshi_f", "text": "「施主來得早。幾知觀清修之地，只接待有缘人。」\n她斟了一杯茶，推至玩家面前。\n「不知施主欲卜問何事？是尋物、問運，還是？」"}, {"me": true, "text": "（我從袖中取出一張泛黃的舊籤紙。）\n「我想解這支卦。這是家中長輩留下的。」"}, {"portrait": null, "who": "daoshi_f", "text": "她沒有接過籤紙，只是看著。\n「唉呀，是老卦案嗎？要是過得時日已久......就得問問『那位』了。」\n她語氣柔和，卻不容置疑。"}, {"bg": "dadian", "place": "正殿・再訪", "text": "回到正殿。\n大師兄仍站在原處，那隻貓依舊蹲在卦案上，瞇著眼假寐。\n牠的尾巴隨意搭在桌緣，籤筒被牠用後腳輕輕勾回案中央，穩如泰山。"}, {"portrait": "daoshi_m", "who": "daoshi_m", "text": "「依規矩，你......」\n他指向案角一處空位。\n「將銅錢與卦案放在那裡。退後三步。」", "choices": [{"key": "c1", "label": "照做，放錢與籤後退", "hint": "守規矩"}, {"key": "c2", "label": "猶豫，先問能否摸貓", "hint": "試探底線", "to": "b1"}]}, {"id": "a1", "me": true, "text": "（我照做，將銅錢與卦案輕輕放在桌緣，然後後退。）", "next": "m1"}, {"id": "b1", "portrait": null, "who": "daoshi_m", "text": "「不可以。」\n他語氣生硬，沒有解釋原因。\n「放著，後退。」"}, {"me": true, "text": "（我收回手，將銅錢與舊籤輕輕放在桌緣，然後後退。）", "next": "m1"}, {"id": "m1", "portrait": "lingshou", "who": "lingshou", "text": "貓睜開一隻眼。\n牠伸出爪子，毫不客氣地將那撮銅錢撥到地上。\n接著，牠低下頭，用前掌穩穩踩住那張舊籤紙。"}, {"me": true, "text": "「我的錢！」\n我急忙想上前，卻被師兄攔下。"}, {"portrait": null, "who": "daoshi_m", "text": "「牠沒趕你走。」\n大師兄盯著地上的銅錢，又看了看被貓踩住的籤紙。\n「但錢不收。」"}, {"portrait": "lingshou", "who": "lingshou", "text": "牠用尾巴掃在木桌上敲了敲，顯得有些不耐煩，隨即轉身背對玩家，一屁股壓住了籤紙。\n喉嚨裡發出低沉的呼嚕聲，像是在嫌棄銅錢太吵。"}, {"who": "lingshou", "text": "「這地方竟是一隻貓作主的嗎？」我不可思議地問，師兄有些怪罪地眼神飄了過來。"}, {"portrait": "daoshi_m", "who": "daoshi_m", "text": "「不是。」師兄為難地斟酌用詞，「我作主，但你要尊重......貓，的規矩，才能留下。」"}, {"bg": "cangjingge", "place": "藏經閣・庫房", "text": "大師兄先是努力地把卦紙從貓的屁股下拖出來看了一眼。\n隨後從架上取下一本積塵的舊簿，翻開細細對照。//\n貓跳上架子，蹲在簿冊上，尾巴垂下蓋住一頁文字。"}, {"portrait": "daoshi_m", "who": "daoshi_m", "text": "「在這裡，師傅......嗯，以前有紀錄這一卦。」\n他指尖點著貓壓住的那一行字。\n「但如此舊事，世事瞬息萬變，這上頭的訊息，也許對你已無意義。」//語畢，他竟抬頭看了貓一眼，像是在徵詢貓的意見。"}, {"portrait": null, "who": "lingshou", "text": "貓伸了個懶腰，爪子隨意搭在簿頁邊緣，沒有挪開的意思。\n牠盯著大師兄，眼神裡帶著一絲不耐煩：『你自己想。』"}, {"portrait": "daoshi_f", "who": "daoshi_f", "text": "「天色已晚，施主如不著急離開，不如入內詳談。」\n她合上手札，微笑。\n「此事還需要點時間詳查，時過境遷，再起一卦也能做個對照，別有趣味，施主覺得如何？」"}, {"me": true, "text": "（我看向大師兄與貓，師兄靜靜地回望與我，我總覺得他想我答應。）\n「我不趕時間！我想知道卦上說了什麼！」"}, {"bg": "xiangfang", "place": "茶室・提醒", "portrait": "daoshi_f", "who": "daoshi_f", "text": "師妹在茶室備下素果，指尖輕抵唇邊。\n「你若留下，每日卯時或者方便替貓添個水？早上見過師兄整理籤筒，下回請你搭把手了，至於觀貓......大人，午睡時不可打擾，貓不沾的地方，你也別去。」\n她目光柔和，卻將規矩說得清楚。"}, {"me": true, "text": "「妳還讓客人給妳家的貓打工？不太正常吧！」"}, {"who": "daoshi_f", "text": "「怎麼會呢？你既來求卦，講求的便是機緣，緣之一字嘛......就是要知行合一，你若不知、不行，又怎麼能起緣分呢，你說是嗎？」"}, {"bg": "dadian", "place": "正殿・夜間", "text": "夜色深沉。油燈昏黃。\n你依約在殿中添水，將散落的籤條一一歸位。\n貓蹲在卦案上，尾巴有一搭沒一搭的掃動。"}, {"text": "大師兄領你穿過迴廊。\n貓走在前頭，尾巴掃過門檻、香爐與貓床。\n每當貓尾劃過一處，大師兄便停步，示意你避讓該處地面。"}, {"bg": "dadian", "portrait": null, "who": "daoshi_m", "text": "師兄將你領至大殿。\n「我去取卦紙，你在此稍作歇息，若還不累也能到處走走，不過別擅動案上的東西。」"}, {"me": true, "text": "「明白。」\n（我放下籤筒時，避開了貓的爪子，那貓的尾巴掃呀掃的，竟放籤筒一馬，沒給推下去。）"}, {"portrait": "lingshou", "me": true, "text": "「小貓，你到底是何方神聖？」"}, {"who": "lingshou", "text": "貓的耳朵轉向你，懶懶地抬起頭。"}, {"who": "lingshou", "text": "「什麼小貓，我能做你爺爺！」"}, {"me": true, "text": "你大吃一驚，差點自己推倒了籤筒！\n「貓說話了！這是成精了？」"}, {"portrait": "daoshi_f", "who": "daoshi_f", "text": "師妹提著燈籠從廊下走來，笑意更深。\n「喵大人認可了你。\n記得每日添水時，別打擾牠午睡。」", "end": true}]$sc$::jsonb, null, '{}'::jsonb, 10, null, '喵喵喵', '觀貓對你開了口，正式認可你暫留觀裡護道。', true)
on conflict (id) do update set character_id = excluded.character_id, chapter = excluded.chapter, seq = excluded.seq,
  title = excluded.title, summary = excluded.summary, require_favor = excluded.require_favor,
  require_cultivation = excluded.require_cultivation, require_event = excluded.require_event,
  scenes = excluded.scenes, choices = null, rewards = excluded.rewards, reward_lingshi = excluded.reward_lingshi,
  reward_avatar = excluded.reward_avatar, reward_title = excluded.reward_title, reward_memory = excluded.reward_memory,
  published = excluded.published;

update character_titles set voice_hint = '話語間時不時會冒出一些喵言喵語，動作也越發貓態，懶散不愛說話，語助詞會不小心加上一個喵字。', description = '這就是一隻貓，怎麼看都是一隻貓。'
 where unlock_event = 'lingshou_c1';

insert into jianghu_events (gua_no, gua, title, doc, published) values
  (1, '乾為天', '龍不歸淵', $jh1${"achievement":{"desc":"讓龍旗不再屬於一個人。","ending":"e6ww3r","name":"見群龍无首"},"achievements":[{"desc":"讓龍旗不再屬於一個人。","ending":"e6ww3r","id":"qun","kind":"ending","name":"見群龍无首","reward_lingshi":30},{"desc":"六爻，各動一回。","id":"liulong","kind":"changes_all","name":"時乘六龍","reward_lingshi":60},{"desc":"每一條路，都走到底。","id":"liuwei","kind":"endings_all","name":"六位時成","reward_lingshi":80},{"desc":"一趟之內，把江湖上帶得走的，都帶在身上。","id":"pinwu","kind":"items_all","name":"品物流形","reward_lingshi":50}],"endings":[{"flags":["登柱"],"hook":{"ask":"師兄，那孩子是不是本來不用死？是不是我......","memory":"剛從山下雲渡鎮回來：擂龍台的少年凌霄帶著斷了的肋骨爬龍柱掛旗，從八丈高處墜下。台下喊他上去的人裡也有你。","who":"daoshi_m"},"id":"e9ay6i","insight":"亢龍有悔，盈不可久也。","need":{},"not_flags":[],"npc_fate":"凌霄從龍柱墜下身亡","player_title":{"call_as":"","desc":"「如果當初......」你總是忍不住對過去悔恨交加。","label":"悔亡"},"rare":false,"reward_lingshi":20,"text":"他爬到了第八丈。\n那面龍旗從潭裡被撈了上來，已濕透了——撈旗的是鐵臂周，他趴在岸邊喘了很久，說了一句「我說過，我只打擂台」。\n第二年春天，龍柱底下多刻了兩個名字。凌老七，凌霄。","title":"亢龍有悔"},{"flags":["拆旗"],"hook":{"ask":"師妹，我把人家的龍旗拆了，觀主回來會不會罵我？","memory":"剛從山下雲渡鎮回來：把擂龍台的龍旗拆成六條，交給渡口六家擺船人輪流管渡，那個叫凌霄的少年活了下來。","who":"daoshi_f"},"id":"e6ww3r","insight":"見群龍无首，吉。","need":{},"not_flags":[],"npc_fate":"凌霄活下來；褚萬金被趕出雲渡","player_title":{"call_as":"","desc":"","label":""},"rare":true,"reward_lingshi":50,"text":"那年秋天以後，雲渡口不再有龍旗。六家擺船人輪流管渡，渡錢定在三文，告示上按了六個手印。\n龍柱底下刻上了凌老七的名字，沒有刻凌霄的——是他自己不肯。\n萬金號的帳後來被縣裡翻了出來，褚萬金連夜走了，再也沒回雲渡。","title":"見群龍无首"},{"flags":["隨捕頭去"],"hook":{"ask":"觀貓，那孩子跟著捕頭走了，算是好事嗎？","memory":"剛從山下雲渡鎮回來：上爻動的那一天，沈捕頭帶走了帶傷的凌霄，回縣裡查萬金號的帳；龍柱最底下那一圈還空著。","who":"lingshou"},"id":"e05w0w","insight":"潛龍勿用，陽在下也。","moves":[5],"need":{},"not_flags":[],"npc_fate":"凌霄活下來，隨沈捕頭回縣裡作證；萬金號被查","player_title":{"call_as":"","desc":"","label":""},"rare":true,"reward_lingshi":40,"text":"凌霄跟著沈捕頭回了縣裡。不是去當帳房，是去當證人——一個具名的證人。\n那面龍旗沒有再掛上去，龍柱最底下那一圈還空著。萬金號的帳查了一整個冬天，渡口的告示換回三文，再也沒有翻過面。\n聽說縣衙的偏房裡住了個年輕人，左肋綁著布，一頁一頁翻三年前的告示存根，翻到自己的畫押就停很久。翻到臘月十七那一頁，他把燈挑亮，坐到了天亮。\n他師父的名字，是第二年開春才刻上龍柱的。刻得很小，沒有人觀禮。","title":"潛龍在淵"},{"flags":["同登","紙鶴"],"hook":{"ask":"師兄，收到紙鶴了嗎？","memory":"{名}在外，掌門命有所不受，雖有頑劣但可堪重任。","who":"daoshi_m"},"id":"e79n1d","insight":"終日乾乾，與時偕行。","need":{},"not_flags":["登柱","拆旗"],"npc_fate":"凌霄活下來，重傷兩月","player_title":{"call_as":"","desc":"","label":""},"rare":false,"reward_lingshi":30,"text":"龍旗掛上去的時候，柱頂的風把你們兩個人都吹得睜不開眼。\n下來以後他躺了兩個月。第三個月，他拄著槍去了渡口，自己在跳板前坐了一整天。\n那天以後，木樁上的告示只剩一面：每人三文。\n龍柱底下刻了凌老七，凌霄的名字刻在旁邊，比師父的小一號。","title":"龍柱之上"},{"flags":["揭局"],"hook":{"ask":"","memory":"","who":""},"id":"e4x9m6","insight":"飛龍在天，利見大人。","need":{"s1":[3,null]},"not_flags":["登柱","拆旗"],"npc_fate":"凌霄活下來，四連冠；褚萬金下獄","player_title":{"call_as":"","desc":"","label":""},"rare":false,"reward_lingshi":30,"text":"萬金號的帳被翻了出來。地契沒讓成；秋分後縣裡核官渡，褚萬金被帶回了縣裡。\n凌霄拿下第四面龍旗，第一件事是把跳板前的護衛換成擺船的人，渡錢改回三文。\n龍柱底下刻了凌老七，他自己的名字刻在旁邊，比師父的小一號。","title":"飛龍在天"},{"flags":["弱揭"],"hook":{"ask":"","memory":"","who":""},"id":"e_weak","insight":"君子終日乾乾，夕惕若。","need":{},"not_flags":["揭局","登柱","拆旗","同登","隨捕頭去"],"npc_fate":"凌霄活下來，洗清但未奪回渡口；褚萬金斷尾脫身","player_title":{"call_as":"","desc":"","label":""},"rare":false,"reward_lingshi":20,"text":"你把泡爛的帳頁舉起來，洗清了凌霄——他分文未取，是真的。\n但褚萬金反應極快，當場把兩個護衛綁了送官，說是「下人私為，萬金號也是受害者」。\n渡口還在萬金號名下，三十文的告示換了一張新的，署名還是凌霄。\n回觀的路上，你在雲渡買了兩條活鯉魚。其中一條，你放回了河裡。","title":"斷尾"},{"flags":[],"hook":{"ask":"","memory":"","who":""},"id":"ea88v3","insight":"君子終日乾乾，夕惕若。","need":{},"not_flags":[],"npc_fate":"","player_title":{"call_as":"","desc":"","label":""},"rare":false,"reward_lingshi":0,"text":"擂龍台散場的時候，天已經黑了。你沒能帶走什麼，只記得那少年站在台上的樣子。\n回觀的路上，你在雲渡買了兩條活鯉魚。","title":"空手而歸"}],"gua":"乾為天","gua_no":1,"id":"gua_01","identity":{"label":"","mode":"disciple","reason":""},"nodes":[{"change":{"scenes":[{"bg":"kezhan","choices":[{"fx":{"s2":1,"s3":1},"get":"泡爛的帳頁","hint":"水冷得刺骨","key":"c4","label":"下河去撈"},{"fx":{"s1":1,"s2":1},"hint":"潛龍勿用","key":"c5","label":"記下時辰，不動","to":"end"}],"place":"山下客棧","text":"夜裡你睡不著，推開客棧的窗。\n河對岸萬金號的後門開了一條縫，有人提著燈籠出來，把一捆東西扔進河裡，不一會兒又縮回門裡去了。"},{"text":"你把那捆東西拖上岸，是一疊泡爛的紙。\n字糊了大半，還認得出幾行：「魁首抽成份額……轉入萬金號修渡」。\n最底下還有一行，墨淡得快看不見：「去年臘月十七，夜渡急件，加錢二兩，凌記。」"}]},"scenes":[{"bg":"guanmen","portrait":"daoshi_f","text":"「山下雲渡鎮寄了封信來。」\n師妹把信遞給你。信紙上的字歪歪斜斜，墨洇了好幾處，像是寫的人手一直在抖。\n「寫信的是渡口一位擺船的婆婆，說今年渡錢漲了三倍，日子難過，求觀裡給一卦——問問擂龍台開了以後，鎮上會不會出事。」","who":"daoshi_f"},{"portrait":"lingshou","text":"「這問的是卦嗎？要的是有人下山給她說句話。」\n觀貓蹲在門檻上舔爪子，眼皮都沒抬。\n「小子，你去。回來帶兩條雲渡的鯉魚，要活的。」","who":"lingshou"},{"portrait":"daoshi_f","text":"師妹笑了笑，把一小袋碎銀塞進你手裡。\n「三兩，省著點花。觀主不在，師兄走不開。{名}，路上當心——到了先別急著出頭，看清楚再說。」","who":"daoshi_f"},{"bg":"dukou","place":"雲渡口","portrait":null,"text":"雲渡口的船擠在一處，沒人撐篙。\n跳板前站著兩個穿靛藍短褂的漢子，一人一只錢簍，過一個收一個。\n岸邊的木樁上釘著一張新告示，紅印蓋在最底下：每人渡錢三十文。\n落款是——擂龍台魁首，凌霄。"},{"npc":"n_aqin","portrait":"n_aqin","speaker":"阿芹","text":"「你就是幾知觀裡來的？」\n老婦人把你從頭打量到腳，又往你身後看了一眼。\n「就你一個？」"},{"me":true,"text":"「婆婆，這三十文渡錢，是那個擂龍台魁首凌霄定的？」"},{"npc":"n_aqin","portrait":"n_aqin","speaker":"阿芹","text":"「你看看這署名，是不是寫的凌霄！」\n她朝告示啐了一口。\n「三年前萬金號的褚老闆出錢把渡口修好，在河上搭了擂龍台。他當著全鎮說：渡口不歸萬金號，歸擂龍台的魁首——誰拿龍旗，誰管這條河。」"},{"npc":"n_aqin","portrait":"n_aqin","speaker":"阿芹","text":"「大家都說褚老闆是善人。」\n她看了一眼跳板前那兩個靛藍短褂。\n「那兩個是魁首的護衛。渡錢從三文漲到十文，今年又漲到三十文——都是魁首的告示。」"},{"me":true,"text":"「你們沒去找凌霄說？」"},{"npc":"n_aqin","portrait":"n_aqin","speaker":"阿芹","text":"「找了！上個月全鎮的人圍著他喊，要他把渡錢降下來。」\n「那孩子站在船頭跟我們說：『渡口年年要修，一文都不收，橋板誰來換？』」\n她的手在膝蓋上搓了兩下。\n「他師父凌老七跟我在這條河上擺了二十年船。老七要是還活著，看見這張紙，非打斷他的腿不可。」"},{"text":"河堤那頭有人喊了一聲：「魁首來了！」\n跳板前的護衛把錢簍往身後一藏，伸手把木樁上的告示一翻——背面還有一張，墨色舊了些：渡錢照舊例，每人三文。魁首凌霄。"},{"choices":[{"fx":{"s2":1},"get":"渡錢告示","hint":"證據先拿在手上","key":"c1","label":"把告示撕下來帶走"},{"cost":1,"fx":{"s1":1,"s4":1},"hint":"一兩碎銀","key":"c2","label":"替婆婆付今天的渡錢"},{"fx":{"s3":1},"hint":"他剛往河灘去了","key":"c3","label":"「我去找他問清楚。」"}],"text":"一個扛槍的少年沿著河堤走過來，衝兩個護衛點了點頭。\n「魁首早。」護衛彎腰，笑得很規矩。\n少年走遠了。護衛等他轉過堤角，才把告示翻回三十文那一面，從身後拿出錢簍。\n阿芹背對著河堤，什麼也沒看見。"},{"text":"暮色壓到河面上的時候，擂龍台那邊傳來一陣喝采——那是資格賽，隔著水聽，像是很遠的地方在打雷。"}],"title":"雲渡口"},{"change":{"scenes":[{"portrait":null,"text":"河堤上一匹馬慢慢走過，馬上的人穿一身皂衣，腰牌在晨光裡晃了一下——縣裡巡河的捕頭。\n凌霄別過臉去，往田裡多走了兩步。"},{"choices":[{"fx":{"s1":1,"s4":1},"get":"沈捕頭的名帖","hint":"利見大人","key":"c10","label":"「大人也覺得貴？」"},{"fx":{"s2":1},"hint":"讓他自己走過去","key":"c11","label":"不搭話","to":"end"}],"npc":"n_shen","portrait":"n_shen","speaker":"沈捕頭","text":"「雲渡今年熱鬧。」捕頭勒住馬，看的卻是渡口那一頭的跳板，「過一個人，收一回錢。」\n他從馬上俯下身，聲音壓低了。\n「貴不貴不歸我管。我管的是——雲渡口是官渡，渡錢三文是縣裡核過的舊例，一文不能多。有人漲到三十文，還把官渡圈起來收。」\n「縣裡收到三封狀子了。狀子上告的是誰，你知道嗎？」\n他看著河灘上那個練槍的少年。\n「告的是凌霄。告示上簽的是他的名字。」"},{"npc":"n_shen","portrait":"n_shen","speaker":"沈捕頭","text":"他把一張名帖塞進你手裡。\n「縣衙大門朝南開。看見什麼，來找沈某。」"}]},"scenes":[{"bg":"dukou","place":"河灘","portrait":null,"text":"天剛亮，河灘的爛泥田裡有人在練槍。\n槍尖挑起泥水，一下，又一下，濺到岸邊看熱鬧的孩子臉上，孩子們尖叫著跑開，又跑回來。"},{"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"「看夠了沒？」\n少年把槍往泥裡一插，抹了把臉上的水。\n「看夠了過來幫我拔，卡住了。」"},{"me":true,"text":"「你就是凌霄？」\n你走過去，「擂龍台魁首竟是個小孩兒？」"},{"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"「你才是小孩兒吧！我十九了！」他得意地笑了一下，「不錯，我就是三連冠的魁首凌霄。」"},{"text":"他伸手去拔槍，拔到一半停住了，左手按在肋下，停了兩息，才把槍從泥裡拔出來。"},{"choices":[{"fx":{"s2":1},"hint":"看見了就說","key":"c6","label":"「你的肋下有傷。」","to":"s_rib"},{"fx":{"s3":1,"s4":1},"hint":"凌老七是什麼人？","key":"c7","label":"「你很尊敬你師父。」","to":"s_master"},{"fx":{"s1":1,"s2":1},"hint":"落款是他的名字","key":"c8","label":"把渡錢告示攤在他面前","req":"渡錢告示","to":"s_notice"}],"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"「明天擂台，第四面龍旗。等我拿到了，鎮上要在龍柱上給我刻名字。」\n他把槍扛上肩。\n「照老規矩，四連冠可以附刻一個名字。我要他們把我師父凌老七的名字刻在我前面。我師父擺了一輩子船，死的時候連塊碑都沒有。」"},{"id":"s_rib","npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"「去年冬天落的，舊傷。」\n他沒看你，低頭把槍尖在袖子上擦乾淨。\n「明天打完就好了。打完我就不幹了，歇一歇。」"},{"me":true,"text":"「你這話可說不得啊......受了傷還爬那麼高的龍柱，不好吧。」"},{"end":true,"npc":"n_lingxiao","speaker":"凌霄","text":"「本來我也覺得夠了......但是褚老闆今年說要在龍柱上刻字，我就動了心思。」"},{"id":"s_master","npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"「我是孤兒，師父撿回來的，也隨他姓。」\n「去年冬天夜裡有人急著過河，那天浪大，本不該出船的……」\n他沒往下說。"},{"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"「三年的獎金，我一文沒亂花，夠給師父立塊碑了。」\n「照規矩魁首管渡口，渡錢裡有一成歸魁首。那一成我不要——渡口是褚老闆修的，我讓他拿去換橋板。」"},{"me":true,"text":"「發心是好的。可渡錢漲到三十文，鎮上的人過不起河了。」"},{"end":true,"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"凌霄愣了一下，「誰說三十文？」\n「渡錢照舊例，三文，一文都沒多收。我天天打渡口過，告示我看過。」\n他把槍往肩上一扛。\n「他們天天來吵，是要我一文都別收。修渡口要錢，這個我不能讓。」"},{"id":"s_notice","npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"「三十文？」\n他把那張紙翻過來，又翻回去。\n「不可能。我每天打渡口過，告示上寫的是三文。」"},{"text":"他拎著告示往渡口走，你跟在後面。\n跳板前的護衛遠遠看見他，臉上先堆起了笑。"},{"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"「這張是怎麼回事？」"},{"text":"護衛接過去看了一眼，一點也不慌。\n「魁首，又是那幫鬧事的貼的。他們想逼您不收渡錢，什麼招都使得出來。那些三十文的，全是他們仿您的名貼的，您別信。」\n他指了指木樁。上頭釘著的，是三文那一張。"},{"end":true,"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"凌霄回頭看你，鬆了口氣。\n「你看。」\n他把那張三十文的告示揉成一團，扔進河裡。"}],"title":"河灘上的小龍"},{"change":{"scenes":[{"bg":"kezhan","place":"巷口","portrait":null,"text":"回客棧的路上，巷口蹲著一個人在啃餅。膀大腰圓，兩條胳膊比你的腿還粗。"},{"me":true,"text":"「你就是鐵臂周？」"},{"choices":[{"fx":{"s2":1},"get":"鐵臂周的口風","key":"c19","label":"「你收了褚掌櫃的錢。」"},{"fx":{"s4":1},"key":"c20","label":"「......那還是個孩子。」"}],"npc":"n_zhou","portrait":"n_zhou","speaker":"鐵臂周","text":"「小道長，明天別往台前頭站。」\n他把最後一口餅塞進嘴裡。\n「我手重，怕濺著你。」"},{"npc":"n_zhou","portrait":"n_zhou","speaker":"鐵臂周","text":"「……過日子，誰嫌錢髒。」\n他站起來，拍掉褲子上的餅渣。\n「褚掌櫃說了，我贏了，明年這渡口歸我管。」\n他往擂台那頭看了一眼。\n「我只打擂台。褚掌櫃教我的，打左肋，他撐不住會自己下台。那孩子能不能活，看他自己知不知道下台。」"}]},"scenes":[{"bg":"wanjin","npc":"n_chu","place":"萬金號","portrait":"n_chu","speaker":"褚萬金","text":"「幾知觀的小道長！」\n萬金號的掌櫃親自迎到門口，一雙手又軟又熱。\n「坐，坐。觀主身子可好？二十年前他老人家在雲渡給我起過一卦，說我這輩子財來財去——你看，準不準。」\n他笑著拍了拍自己的肚子。"},{"me":true,"text":"「準。掌櫃找我，不是為了敘舊吧。」"},{"choices":[{"fx":{"s1":1,"s3":1},"key":"c39","label":"「你給我上套呢？」"},{"fx":{"s2":1,"s4":1},"key":"c40","label":"「......我可不敢起這卦。」"}],"npc":"n_chu","portrait":"n_chu","speaker":"褚萬金","text":"「爽快。」\n他親手給你斟酒。酒很好。\n「明天的擂台，想請小道長替凌霄那孩子看一卦，看他能不能贏。贏了，渡口的生意一年穩當；輸了——」\n他把酒杯轉了半圈。\n「唉呀，不會輸的、不會輸的，瞧我這烏鴉嘴，大家可都盼著凌霄再次奪得龍旗，就等小道長起一卦給大家安安心！」"},{"npc":"n_chu","portrait":"n_chu","speaker":"褚萬金","text":"褚萬金哈哈一笑，也不惱。\n「鎮上的賭攤，十個人裡九個押小龍，賠率一賠不到一，莊家都快哭了。」\n他壓低聲音，像在說一件好事。\n「小道長一卦說他贏，大家押得更安心——這是積德。」"},{"choices":[{"fx":{"s1":-1,"s3":2,"s5":5},"get":"褚掌櫃的賄賂","hint":"沉甸甸的，夠你花好一陣子","key":"c12","label":"收下錦囊","to":"s_night"},{"fx":{"s1":1},"hint":"酒喝了，錢不收","key":"c13","label":"把錦囊推回去","to":"s_night"},{"fx":{"s2":1},"hint":"假意答應，散席後去帳房","key":"c14","label":"「......卦我替您看看。」","to":"s_ledger"}],"text":"桌底下，一只錦囊推到了你手邊，沉甸甸的。"},{"choices":[{"key":"c15","label":"回客棧睡覺","to":"end"},{"fx":{"s2":1},"hint":"夕惕若，厲","key":"c16","label":"繞到帳房窗下"}],"id":"s_night","text":"散席時已近三更。萬金號的燈一盞一盞熄了，只剩帳房那扇窗還亮著。"},{"id":"s_ledger","text":"帳房裡沒人。桌上攤著一本帳，墨跡還沒乾：\n渡錢三十文，十之七入萬金號，三成分護衛。\n魁首抽成份額轉入萬金號修渡。"},{"me":true,"text":"（凌霄這是分文未取嗎？）"},{"choices":[{"fx":{"s2":1,"s3":1},"get":"萬金號帳本","key":"c17","label":"把帳本揣進懷裡"},{"fx":{"s2":2},"hint":"不讓他知道有人來過","key":"c18","label":"只記下內容，原樣放回"}],"text":"帳本夾層掉出一張紙，是渡口告示的「用印授權」，底下有凌霄的畫押——三年前他剛拿第一面旗時簽的，當時他大概以為只是「魁首管事」的例行文書。\n旁邊一行小字：渡口凡有事故，具名者擔。\n帳本最後一頁另起，字寫得很小：\n擂台賭盤，莊家押周，三千兩。\n鐵臂周，五十兩。\n再下一行，墨色舊些：「去年臘月十七，夜渡急件，加錢二兩，凌記。船翻，人沒。」"}],"title":"萬金號的晚宴"},{"change":{"scenes":[{"choices":[{"fx":{"s3":1,"s4":1},"key":"c25","label":"二話不說跳下水撈人"},{"fx":{"s1":1},"key":"c26","label":"抓住欄杆，把凌霄往岸上推"}],"text":"打到一半，台底下傳來一聲裂響——東南角那根木樁在水裡泡了三年，終於撐不住了。\n整座擂台往潭裡斜過去。凌霄還沒站穩，腳一滑，摔進了湍急的雲渡河裡。"},{"end":true,"npc":"n_zhou","speaker":"鐵臂周","text":"鐵臂周也跳下去了。他把凌霄從水裡托上來，自己趴在岸邊喘得像頭牛。\n「我說過，我只打擂台。」"}]},"scenes":[{"bg":"leitai","place":"擂龍台","portrait":null,"text":"擂龍台搭在河上，四根粗木樁打進水裡，台底下就是深潭。\n雲渡兩岸擠得水洩不通，賭攤的吆喝比銅鑼還響。\n押凌霄的籌子堆成了小山；押鐵臂周的那一格空著，只有一個不知名的人往裡頭推了整整一箱銀子。"},{"text":"凌霄連過三場，已氣喘吁吁，他眼神明亮，戰意正勝。\n但你注意到他一瞬間露出的痛苦皺眉。\n第四場，鐵臂周上台。"},{"text":"過到第七招，凌霄失了準頭，周的拳頭擦過槍桿，結結實實砸在凌霄左肋上。\n少年橫飛出去，撞上台邊的木樁，槍脫了手，掉進潭裡。\n台下靜了一瞬，接著炸開了。"},{"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"他扶著木樁站起來，嘴角掛著血。\n「再來。」"},{"choices":[{"fx":{"s3":2},"hint":"或躍在淵","key":"c21","label":"躍上擂台","to":"so259o"},{"fx":{"s1":1,"s3":1},"hint":"當眾說破","key":"c22","label":"「周收了萬金號五十兩！」","req":["萬金號帳本","鐵臂周的口風"],"to":"swoo3s"},{"fx":{"s4":2},"get":"六家船號","hint":"一個人喊，沒人聽","key":"c23","label":"回渡口叫擺船的人","to":"sb09gl"},{"fx":{"s2":1},"hint":"這是他的擂台","key":"c24","label":"站在台下看","to":"sshv61"},{"cost":3,"fx":{"s1":1,"s4":1},"hint":"三兩銀子","key":"c90","label":"把盤纏拍在船頭，請船家下潭撈槍","to":"s_buyspear"}],"npc":"n_chu","portrait":"n_chu","speaker":"褚萬金","text":"「好！小龍還能打！不過你受傷又失了武器，不可勉強！」\n褚萬金在看台上帶頭拍手。\n「諸位也不想見你血濺擂台呀！今年是否就暫避鋒芒、休養生息為好？」\n那些個押寶凌霄的人瞬間躁動了起來。"},{"id":"so259o","text":"你翻上擂台，木板晃了一下。\n周看了你一眼，又往看台上看了一眼。"},{"end":true,"npc":"n_zhou","portrait":"n_zhou","speaker":"鐵臂周","text":"「小道長，」鐵臂周把拳頭放下了，「我說過，我手重。」"},{"end":true,"id":"swoo3s","text":"你的聲音不大，但離得近的幾個賭客都回過頭來。有人笑，有人罵你是哪來的野道士。\n看台上，褚萬金沒笑。他的手指在扶手上敲了兩下。"},{"end":true,"id":"sb09gl","text":"你擠出人群，往渡口跑。阿芹的船還拴在老地方。\n她聽你說完，一句也沒問，扯開嗓子朝河上喊了一聲。六條船上的人同時抬起頭來。"},{"end":true,"id":"sshv61","text":"凌霄沒有認輸。\n他空著手，又撲了上去。"},{"end":true,"id":"s_buyspear","text":"你把身上的碎銀全拍在船頭。\n一個船家掂了掂，二話不說翻身下水。槍撈上來時還在滴水，你揚手拋回台上，凌霄一把接住。\n他回頭看了你一眼，沒說話。"}],"title":"擂龍台"},{"change":{"scenes":[{"text":"一隻灰鴿落在你肩上，腳上綁著一卷紙。是大師兄的字，只有一行。"},{"portrait":null,"text":"「亢龍有悔，切莫躁進。」","who":"daoshi_m"},{"choices":[{"fx":{"s1":1},"get":"師兄的小抄","hint":"師兄的字真好看","key":"c31","label":"把紙條小心收進懷裡"},{"fx":{"s3":1},"hint":"弟子在外，掌門命有所不受！","key":"c32","label":"把紙條折成紙鶴，讓飛鴿帶回","set":"紙鶴"}],"me":true,"text":"「師兄怎麼知道龍柱的事……」"}]},"scenes":[{"bg":"leitai","portrait":null,"text":"凌霄第五次從台上爬起來的時候，鐵臂周把拳頭放下了。\n他朝看台上的褚萬金看了一眼，轉身跳下擂台，頭也不回地往人群外頭走。\n按規矩，自己下台的算輸。"},{"npc":"n_chu","portrait":"n_chu","speaker":"褚萬金","text":"賭攤那邊炸開了鍋，押凌霄的人在搶銀子。\n褚萬金的臉白了一瞬，又笑起來，擠到台前，笑得比誰都響。\n「四連冠！小龍，管渡口太累人，這張簽了，以後萬金號替你管，抽成照給你！」\n他把一張紙和一支筆舉到凌霄面前。"},{"choices":[{"fx":{"s1":2,"s2":1},"hint":"十之七入萬金號","key":"c27","label":"把帳本舉起來","req":"萬金號帳本","set":"揭局","to":"s6mts5"},{"fx":{"s1":1,"s3":1},"hint":"利見大人","key":"c28","label":"「沈捕頭，請上台。」","req":"沈捕頭的名帖","set":"揭局","to":"s6zc4p"},{"fx":{"s1":1,"s4":2},"key":"c29","label":"讓擺船的人上台","req":"六家船號","to":"sz0lx9"},{"fx":{"s2":1},"hint":"讓他自己決定","key":"c30","label":"搖頭","to":"sxf26g"},{"fx":{"s1":1},"hint":"字糊了大半","key":"c43","label":"把泡爛的帳頁舉起來","req":"泡爛的帳頁","set":"弱揭","to":"s_weak"}],"text":"紙上寫的不是抽成，是「雲渡口地契讓渡」。\n地契下面還壓著第二張——具結書：魁首自願將渡口管理全權委予萬金號，往來帳目由魁首具名。\n凌霄一簽，等於親手把「錢是我收的」寫成白紙黑字。\n少年低頭看著那兩張紙，沒有接筆。他回過頭，在人群裡找到了你。"},{"end":true,"id":"s6mts5","text":"你把帳本舉過頭頂，一頁一頁翻給台下看。\n前排有人識字，念出了聲：「告示二式……魁首過渡，換三文那張……」\n凌霄的手抖了一下。 //\n「三文……是你們給我看的那張。」\n褚萬金伸手來搶，被你躲開了。\n他臉色一變，反咬一口：「小道長，告示上寫的是他的名字，錢簍是他的護衛提的。縣裡要查，先查他。」"},{"end":true,"id":"s6zc4p","npc":"n_shen","portrait":"n_shen","speaker":"沈捕頭","text":"皂衣捕頭撥開人群走上台，把腰牌往桌上一擱。\n「褚掌櫃。雲渡口登記官渡，渡錢三文，舊例。誰准你漲到三十？這張地契，你拿什麼讓？」"},{"end":true,"id":"sz0lx9","npc":"n_aqin","portrait":"n_aqin","speaker":"阿芹","text":"六條船靠到擂台邊。阿芹第一個上台，伸手把凌霄手裡的筆拿走，掰成兩截，扔進河裡。\n「老七的徒弟，不簽這種東西。」"},{"end":true,"id":"sxf26g","npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"他看著你，點了一下頭，把筆接了過去，在紙上寫了兩個字。\n褚萬金低頭一看，臉色變了。\n不是名字。是「狗屁」！\n褚萬金的笑僵在臉上，退了半步，又強笑起來：「小龍年輕氣盛，諸位見笑了——這地契的事，改日再議。」"},{"end":true,"id":"s_weak","text":"你把泡爛的帳頁舉起來，字糊了大半，只認得出「魁首抽成份額……轉入萬金號修渡」。\n凌霄分文未取，是真的。但三十文的拆分、賭盤押周，一個字也沒有。\n褚萬金的反應極快：「護衛所為！我萬金號也是受害者！」他當場叫人把兩個靛藍短褂綁了。\n沈捕頭看了你一眼——那眼神是：你只救得了一個人。\n凌霄站在台上，手裡還握著那張具結書，沒簽，也沒放。"}],"title":"龍旗"},{"change":{"scenes":[{"choices":[{"fx":{"s4":2},"key":"c37","label":"站到他們中間"},{"fx":{"s2":1},"key":"c38","label":"看著","to":"sii73r"}],"text":"人群裡不知道是誰先開的口：「憑什麼一個人說了算？」\n接著是第二個人，第三個人。擺船的、挑擔的、賣魚的，聲音從四面八方湧上來。\n"},{"after":["c33","c34","c36"],"choices":[{"fx":{"s2":1},"hint":"把名字從告示上摘下來，得從縣衙開始","key":"c41","label":"「凌霄，跟他去吧。」","set":"隨捕頭去","to":"sqlz01"},{"fx":{"s4":1},"hint":"雲渡的事還沒完","key":"c42","label":"「他哪兒也不去。」","to":"end"}],"id":"sii73r","npc":"n_shen","portrait":null,"speaker":"沈捕頭","text":"皂衣捕頭不知什麼時候已經站在人群外，腰牌在暮色裡晃了一下。\n「萬金號的帳，縣裡要從頭查。可狀子上具名的是他。」\n他看的是凌霄。\n「傷養好之前，跟我回縣裡——不是請你，是傳你。」"},{"after":["c35"],"end":true,"npc":"n_shen","portrait":null,"speaker":"沈捕頭","text":"沈捕頭的馬到柱下時，人已經從潭裡撈上來了。\n他下了馬，在凌霄身邊站了很久，才把腰牌收回懷裡。\n「……來晚了。」"},{"id":"sqlz01","npc":"n_lingxiao","portrait":null,"speaker":"凌霄","text":"凌霄低頭看了看自己的手，又抬頭看了一眼龍柱。\n「……那師父的名字呢？」"},{"end":true,"npc":"n_shen","portrait":null,"speaker":"沈捕頭","text":"「帳算清了，自然有人替他刻。」\n他把韁繩遞過去。\n「上馬。肋骨斷了，就別走路。」"}]},"scenes":[{"bg":"longzhu","place":"龍柱","text":"按雲渡的老規矩，魁首要親手把龍旗掛上龍柱頂。龍柱九丈，柱身刻滿了往年魁首的名字，最底下那一圈還空著。"},{"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"他把龍旗綁在背上，手按著左肋，抬頭看柱頂。\n「爬上去，掛好了，他們就得把師父的名字刻上去。」"},{"npc":"n_aqin","portrait":"n_aqin","speaker":"阿芹","text":"「傻孩子，別逞強，你那根骨頭指定是斷了！」"},{"choices":[{"fx":{"s1":1,"s4":1},"hint":"旗掛不掛，你都是魁首","key":"c33","label":"攔住他","set":"攔下","to":"sk7zx5"},{"fx":{"s3":1,"s4":1},"hint":"摔下來有人接著","key":"c34","label":"陪他一起爬","set":"同登","to":"sb4ctz"},{"fx":{"s1":-2,"s3":2},"hint":"這是他的龍柱","key":"c35","label":"「上去！」","set":"登柱","to":"skk6oa"},{"fx":{"s1":1,"s4":2},"hint":"見群龍无首","key":"c36","label":"把龍旗搶過來","req":"六家船號","set":"拆旗","to":"sm89oz"}],"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"「......我還能上！」"},{"id":"sk7zx5","text":"你抓住他的手腕。他掙了一下，沒掙開——\n或者他已經沒有力氣掙開了。"},{"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"「我師父的名字……」"},{"end":true,"me":true,"text":"「你師父可沒有讓你拿命給他刻字！」"},{"id":"sb4ctz","text":"你們爬到第六丈的時候，他的手開始抖。你在下面托著他的腳，一寸一寸往上送。 //\n風很大，龍旗在他背上拍得劈啪響。"},{"me":true,"text":"「走！」你也累得夠嗆，但見凌霄眼神明亮，鬥志昂揚。\n你不肯鬆手，凌霄的腳也踩得更穩妥。"},{"end":true,"text":"那面旗幟終於掛上了龍柱，底下眾人齊聲歡呼。 //\n你從上頭見著阿芹悄悄拭淚，褚萬金的臉一陣青一陣白的。\n凌霄與你相視一笑。"},{"id":"skk6oa","text":"台下的人跟著你喊起來。上去！上去！\n凌霄笑了一下，將龍旗在背上繫穩妥了，開始往上爬。\n爬到第八丈，他停住了，他的手在顫抖。"},{"npc":"n_zhou","portrait":"n_zhou","speaker":"鐵臂周","text":"「......還是太年輕了，為這虛名竟拿命去拚搏......」\n話未完，人群驚呼聲四起，凌霄身形一顫，手一鬆－－"},{"npc":"n_aqin","portrait":"n_aqin","speaker":"阿芹","text":"「凌霄！」"},{"end":true,"npc":"n_chu","speaker":"褚萬金","text":"「唉呀！」褚老闆惋惜地大喊，「快來人看看小龍！小龍要是不行了，那今年魁首就是周－－」"},{"id":"sm89oz","text":"你趁他不備，從他背上解下龍旗。\n接過阿芹遞來的割纜刀，沿著旗面的縫線割下去。\n一面旗，割成六條。"},{"me":true,"text":"「六條船，一家一條。」\n你把布條遞給阿芹。\n「這渡口就你們六家輪著管。」"},{"npc":"n_lingxiao","portrait":"n_lingxiao","speaker":"凌霄","text":"凌霄錯愕地看著那六條布，很久沒說話。\n「輪著管嗎......師父要是看見——」"},{"end":true,"npc":"n_aqin","portrait":"n_aqin","speaker":"阿芹","text":"「要是看見你再爬上去，他會打斷你的腿。」"}],"title":"龍柱"}],"note":"Claude 範本（2026-10-21）：要在下一版 App 裡驗證手感。缺圖的場景先借舊圖（渡口、龍柱借山下客棧，擂台借後院），立繪見「美術需求」頁；靈石數字暫定。\n10-24：DeepSeek 校稿版併入（用印授權／具結書、凌老七夜渡、沈捕頭傳證人、斷尾結局）；四爻 c22 帶帳本或周的口風任一樣。","npcs":[{"desc":"十九歲，雲渡鎮擂龍台三年魁首，人稱小龍。師父凌老七是擺了一輩子船的老船夫，去年冬天走了，連塊碑都沒有。左肋有舊傷。三年前剛拿第一面旗時，簽過一張看不懂的「渡口用印授權」——渡口凡有事故，具名者擔。","id":"n_lingxiao","name":"凌霄"},{"desc":"萬金號掌櫃、擂龍台的東家。逢人先笑，渡口的錢從他手裡過。今年縣裡三封狀子壓下來、秋分後要核官渡，他必須在查帳前把地契洗乾淨。帳本末頁記著凌老七死的那晚——萬金號加錢催的船。他心虛，所以更要凌霄簽字頂罪。","id":"n_chu","name":"褚萬金"},{"desc":"渡口擺了三十年船的老婦人，寫信到幾知觀求卦的人。跟凌老七在同一條河上擺了二十年船。她知道那晚河上有人提燈籠喊船，喊得急；她求的不是渡錢的卦，是別讓第二個凌老七死在這條河上。","id":"n_aqin","name":"阿芹"},{"desc":"外地來的挑戰者，兩條胳膊比人腿粗。收了褚萬金五十兩，要打凌霄的左肋。只打擂台，不想殺人。褚教他「打左肋，他撐不住會自己下台」，他以為這是不用殺人的乾淨贏法。上爻若在場，是他把凌霄從潭裡撈上來的。","id":"n_zhou","name":"鐵臂周"},{"desc":"縣裡巡河的捕頭，話少，腰牌比人先到。不是青天，是有案子的官。他動不了褚，需要一個外地證人＋一本帳。狀子上告的是凌霄——告示上簽的是他的名字。","id":"n_shen","name":"沈捕頭"}],"opening":{"bg":"guanmen","text":"秋分前三天，一封從山下寄來的信，在觀門的門縫裡卡了一夜。"},"outline":{"achievement_dir":"見群龍无首：讓龍旗不再屬於一個人。","conflict":"凌霄要第四面龍旗給亡師立名，也要保住「魁首」這個能刻名字的身分；褚萬金押周、要地契，還要凌霄簽下具結書頂罪；鎮民被三十文渡錢壓著卻罵錯了人；捕頭要證據，狀子上告的是凌霄。","core_question":"一條龍飛到最高處之後，要不要讓他再往上爬？——爬上去，旗掛了、名字刻了，這孩子就再也摘不乾淨。","ending_dirs":"拆旗交給六家（群龍无首）；喊他上去墜亡（亢龍有悔）；上爻動時隨捕頭去作證（潛龍在淵，稀有）；揭帳本四連冠（飛龍在天）；陪他同登（龍柱之上）；只拿到泡爛的帳頁、褚萬金斷尾（斷尾）；空手而歸。","must_avoid":"","must_include":"","player_role":"幾知觀弟子，因渡口阿芹婆婆寫信求卦下山。她求的不是渡錢的卦，是別讓第二個凌老七死在這條河上。","player_summary":"山下雲渡鎮的擂龍台，今年要出第一個四連冠。四連冠者，可附刻一個名字在龍柱上。","plot":"初：到渡口看見告示（潛）；二：河灘見到凌霄與沈捕頭（見龍在田）；三：萬金號夜宴與帳房，看見凌霄三年前簽的用印授權（夕惕若）；四：擂台、肋骨斷（或躍在淵）；五：龍旗與簽字，具結書壓在地契下（飛龍在天，利見大人）；上：龍柱（亢龍有悔）。","source_notes":"爻位對應：初九潛龍勿用→初節；九二見龍在田→二節；九三終日乾乾夕惕若→三節（夜）；九四或躍在淵→四節（擂台下是深潭）；九五飛龍在天→五節；上九亢龍有悔→龍柱。用九見群龍无首→成就結局。\n\n【原匯入大綱，保留對照】主題：權力頂峰與盛極而衰；摘要：玩家獲得盟主繼任機會，卻發現權力建立在被隱瞞的冤案上。；結局方向：登位後因過度擴張而反噬；以實績取得公信力；退居幕後保全力量；挑起衝突導致失局。；成就方向：亢龍有悔：符合指定路線與條件後解鎖，不向玩家解釋內部卦理分類。","summary":"褚萬金修了渡口、辦擂台賺錢，為了善人的名聲把渡口掛在魁首名下；護衛是他的人，魁首在時換三文的告示，人一走就收三十文。凌霄只拿獎金、讓出抽成，以為鎮民吵著要他免收渡錢。今年褚萬金在賭盤重押買來的鐵臂周，要換自己人當魁首、拿走地契；縣裡的捕頭正在查官渡被圈地收錢。帳本上有一行舊帳：凌老七死的那晚，是萬金號加錢催的船。","theme":"乾：元亨利貞。六龍由潛而亢；用九「見群龍无首，吉」。凌霄是具名的魁首，卻從沒碰過一毛渡錢；告示上寫著他的名字，錢簍由護衛提著。玩家要救的不是渡錢，是別讓十九歲的孩子替褚萬金扛罪。"},"start":{"s5":3},"status":"final","title":"龍不歸淵","tone":"heavy","updated_at":"2026-11-01T13:33:30.764Z"}$jh1$::jsonb, true)
